SourceCode.Declaration:
/// <summary>
/// COC for receive on transfer order
/// </summary>
[ExtensionOf(classStr(InventTransferMultiReceive))]
final class METInventTransferMultiReceive_Extension
{

}

Method.Source:
/// <summary>
/// Initializes the <c>InventTransferMultiReceive</c> object from the given <c>Args</c> instance.
/// </summary>
/// <param name = "_args">
/// The <c>Args</c> instance to initialize from.
/// </param>
protected void initFromArgs(Args _args)
{
    next initFromArgs(_args);

    if (_args.dataset() == tableNum(InventTransferTable))
    {
        InventTransferTable         inventTransferTable;
        InventTransferParmTable     inventTransferParmTableLoc;
        InventTransferParmLine      inventTransferParmLine;

        inventTransferTable = _args.record();

        if (inventTransferTable.RecId)
        {
            select firstonly TransferId, ParmId from inventTransferParmTableLoc order by RecId desc
                where inventTransferParmTableLoc.TransferId == inventTransferTable.TransferId;

            ttsbegin;
            while select forupdate inventTransferParmLine
                where inventTransferParmLine.TransferId == inventTransferParmTableLoc.TransferId
                    && inventTransferParmLine.ParmId == inventTransferParmTableLoc.ParmId
            {
                inventTransferParmLine.METUOM           = METConstants::unitEach;
                inventTransferParmLine.METSellUOM       = inventTransferParmLine.itemSellUOM(inventTransferParmLine);
                inventTransferParmLine.METCases         = inventTransferParmLine.itemConvertCases(inventTransferParmLine);
                inventTransferParmLine.METOrigQty       = inventTransferParmLine.QtyReceiveNow;
                inventTransferParmLine.METOrigCases     = inventTransferParmLine.METCases;
                inventTransferParmLine.update();
            }
            ttscommit;
        }
    }
}
